import * as THREE from 'three';

const $ = (id) => document.getElementById(id);
const sceneCanvas = $('scene');
const renderer = new THREE.WebGLRenderer({ canvas: sceneCanvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9eb7c5);
scene.fog = new THREE.Fog(0x9eb7c5, 180, 850);
const camera = new THREE.PerspectiveCamera(64, innerWidth / innerHeight, 0.1, 1200);
const clock = new THREE.Clock();
const hemi = new THREE.HemisphereLight(0xcfe8ff, 0x586348, 2.0); scene.add(hemi);
const sun = new THREE.DirectionalLight(0xffddb0, 3.2); sun.position.set(-110, 180, 80); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -180; sun.shadow.camera.right = 180; sun.shadow.camera.top = 180; sun.shadow.camera.bottom = -180; scene.add(sun);

const mat = (color, roughness=0.8, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  grass: mat(0x697b55), road: mat(0x30363a), line: mat(0xe4d5a5), sidewalk: mat(0x9a9b91),
  white: mat(0xe6e1d3), dark: mat(0x171c22, .45), glass: new THREE.MeshStandardMaterial({color:0x557483, roughness:.25, metalness:.25}),
  tire: mat(0x141619), tree: mat(0x405e42), trunk: mat(0x66513b), rock: mat(0x6d706a),
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(1600,1600), mats.grass); ground.rotation.x=-Math.PI/2; ground.position.y=-.12; ground.receiveShadow=true; scene.add(ground);
const world = new THREE.Group(); scene.add(world);

function box(parent, material, x,y,z, sx,sy,sz, cast=false) {
  const mesh = new THREE.Mesh(boxGeo, material); mesh.position.set(x,y,z); mesh.scale.set(sx,sy,sz); mesh.castShadow=cast; mesh.receiveShadow=true; parent.add(mesh); return mesh;
}
function cylinder(parent, material, x,y,z, rTop,rBottom,h, sides=8) {
 const m=new THREE.Mesh(new THREE.CylinderGeometry(rTop,rBottom,h,sides),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;
}
// Urban grid: broad avenues, sidewalks, lane markings and varied mid-rise blocks.
for(let x=-260;x<=260;x+=100) {
  box(world,mats.road,x,.005,0,15,.08,570);
  box(world,mats.sidewalk,x-9,.05,0,3,.18,570); box(world,mats.sidewalk,x+9,.05,0,3,.18,570);
  for(let z=-275;z<=275;z+=24) box(world,mats.line,x,.055,z, .16,.015,8);
}
for(let z=-260;z<=260;z+=100) {
  box(world,mats.road,0,.01,z,570,.08,15);
  box(world,mats.sidewalk,0,.05,z-9,570,.18,3); box(world,mats.sidewalk,0,.05,z+9,570,.18,3);
  for(let x=-275;x<=275;x+=24) box(world,mats.line,x,.06,z,8,.015,.16);
}
const buildingColors=[0x777e81,0xa18b72,0x697580,0xb09e83,0x64706f,0x8c8179,0x596875];
let seed=98451; const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
for(let bx=-250;bx<250;bx+=100) for(let bz=-250;bz<250;bz+=100) {
  for(let ix=0;ix<2;ix++) for(let iz=0;iz<2;iz++) {
    if(rand()<.12) continue;
    const x=bx+(ix?30:-30), z=bz+(iz?30:-30), w=22+rand()*22, d=22+rand()*22, h=15+rand()*55;
    const bmat=mat(buildingColors[Math.floor(rand()*buildingColors.length)],.83);
    box(world,bmat,x,h/2,z,w,h,d,true);
    box(world,mat(0x303c44,.65),x,h+.35,z,w+.6,.7,d+.6);
    // roof units and sparse window bands provide readable city detail cheaply.
    if(rand()>.35) box(world,mat(0x4a5154),x+(rand()-.5)*8,h+1.5,z+(rand()-.5)*8,4,2.4,4);
    const winmat=mat(0x91b3bb,.35,.15);
    for(let yy=5;yy<h-3;yy+=6) {
      box(world,winmat,x-w*.25,yy,z-d/2-.012,w*.22,.8,.025);
      box(world,winmat,x+w*.25,yy,z-d/2-.012,w*.22,.8,.025);
    }
  }
}
// Mountain ridge silhouettes and switchback road in the northern valley.
for(let i=0;i<42;i++) {
  const x=-390+rand()*780, z=-410-rand()*260, h=90+rand()*170, r=55+rand()*85;
  const peak=new THREE.Mesh(new THREE.ConeGeometry(r,h,6),mat(i%3?0x687a72:0x899083));
  peak.position.set(x,h*.48,z); peak.rotation.y=rand()*Math.PI; peak.castShadow=true; scene.add(peak);
  const cap=new THREE.Mesh(new THREE.ConeGeometry(r*.38,h*.3,6),mat(0xd0d0c4)); cap.position.set(x,h*.86,z);cap.rotation.y=peak.rotation.y;scene.add(cap);
}
const mountainPoints=[];
for(let i=0;i<=100;i++){const t=i/100;mountainPoints.push(new THREE.Vector3(Math.sin(t*Math.PI*4)*115,1+Math.sin(t*Math.PI)*24,-300-t*420));}
const mountainCurve=new THREE.CatmullRomCurve3(mountainPoints);
const roadGeom=new THREE.TubeGeometry(mountainCurve,240,8,6,false);
const mountainRoad=new THREE.Mesh(roadGeom,mats.road); mountainRoad.scale.y=.035; mountainRoad.position.y=0; mountainRoad.receiveShadow=true;scene.add(mountainRoad);
for(let i=0;i<=100;i+=2){const p=mountainCurve.getPoint(i/100);box(scene,mats.line,p.x-8,.4,p.z,.18,.05,2);}
// Roadside trees, lamp posts and palms, intentionally kept low-poly.
for(let i=0;i<170;i++) {
 const x=(rand()-.5)*650, z=(rand()-.5)*620;
 if(Math.abs(x%100)<19||Math.abs(z%100)<19) continue;
 const scale=.75+rand()*1.1; cylinder(world,mats.trunk,x,2*scale,z,.45*scale,.65*scale,4*scale,6);
 const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(3.2*scale,1),mats.tree);crown.position.set(x,5.2*scale,z);crown.castShadow=true;world.add(crown);
}
for(let x=-200;x<=200;x+=100) for(let z=-220;z<=220;z+=100) {
  cylinder(world,mat(0x4a4b46),x+13,3,z+13,.12,.12,6,6);
  const lamp=new THREE.Mesh(new THREE.SphereGeometry(.48,8,6),new THREE.MeshBasicMaterial({color:0xffe6a8}));lamp.position.set(x+13,6,z+13);scene.add(lamp);
}

// Detailed but lightweight vehicle assembly used for the player's car and traffic.
function makeCar(color=0xe85b2a, player=false) {
 const root=new THREE.Group(), paint=mat(color,.36,.48), trim=mat(0x17191c,.42,.25), glass=mat(0x263e49,.18,.35);
 box(root,paint,0,.78,0,2.1,.62,4.35,true); box(root,paint,0,1.26,.15,1.68,.7,2.15,true);
 box(root,glass,0,1.31,-.42,1.52,.52,1.02); box(root,glass,0,1.31,.87,1.48,.46,.74);
 box(root,trim,0,.52,-1.7,1.82,.12,.58); box(root,trim,0,.5,1.75,1.86,.13,.48);
 box(root,mat(0xf6f0dc,.3),-.67,.82,-2.2,.42,.2,.08);box(root,mat(0xf6f0dc,.3),.67,.82,-2.2,.42,.2,.08);
 box(root,mat(0xef3028,.3),-.68,.83,2.2,.42,.18,.08);box(root,mat(0xef3028,.3),.68,.83,2.2,.42,.18,.08);
 const wheels=[];
 for(const x of [-1.04,1.04]) for(const z of [-1.38,1.38]) {
  const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.28,12),mats.tire);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.43,z);wheel.castShadow=true;root.add(wheel);wheels.push(wheel);
  const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.3,10),mat(0x9ba5ab,.3,.7));hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);root.add(hub);
 }
 if(player){
  box(root,mat(0x171a20,.7),0,1.64,.06,.12,.1,.75);
  // subtle orange front splitter
  box(root,mat(0xff7c28,.35,.3),0,.49,-2.21,1.75,.09,.16);
 }
 root.position.y=0;scene.add(root);return {root,wheels};
}
const player=makeCar(0x168ca5,true); player.root.position.set(0,0,9);
const traffic=[];
const trafficColors=[0xf1eee4,0xc74a35,0x35414b,0x739066,0xd1a843,0x496b8c,0x282b30,0x9ba9a5,0xa85c83,0xdddddc];
for(let i=0;i<30;i++) {
 const v=makeCar(trafficColors[i%trafficColors.length]);
 const lane=(i%2?1:-1)*3.2, roadIndex=(Math.floor(i/2)%5)-2;
 const axis=i%4, t=25+Math.floor(i/8)*60;
 if(axis<2){v.root.position.set(roadIndex*100+lane,0,axis===0?-t:t);v.root.rotation.y=axis===0?0:Math.PI;}
 else {v.root.position.set(axis===2?-t:t,0,roadIndex*100+lane);v.root.rotation.y=axis===2?Math.PI/2:-Math.PI/2;}
 traffic.push({ ...v, axis, lane, roadIndex, speed:8+rand()*9, dir:axis===0||axis===2?1:-1, wait:0, baseX:v.root.position.x,baseZ:v.root.position.z });
}
const raceCars=[];
for(let i=0;i<3;i++){const c=makeCar([0xe4bd43,0x9c56c7,0x51b56a][i]);raceCars.push({ ...c, progress:0, speed:19+i*1.6, lane:(i-1)*3.3 });}

const input={left:false,right:false,throttle:false,brake:false,handbrake:false,nitro:false};
let driveMode='normal', cameraMode=1, selectedEvent='free', playing=false, paused=false, soundOn=true, quality='auto';
let speed=0, yaw=0, lateral=0, nitro=100, driftScore=0, combo=1, driftTime=0, driftActive=false;
let elapsed=0, eventTime=0, checkpoint=0, eventStarted=false, finishAt=0, toastUntil=0, lastUi=0;
const checkpoints=[];
const cityRoute=[new THREE.Vector3(0,0,-80),new THREE.Vector3(100,0,-100),new THREE.Vector3(200,0,-100),new THREE.Vector3(200,0,0),new THREE.Vector3(100,0,100),new THREE.Vector3(0,0,100),new THREE.Vector3(-100,0,100),new THREE.Vector3(-200,0,0),new THREE.Vector3(-100,0,-100)];
const mountainRoute=Array.from({length:9},(_,i)=>mountainCurve.getPoint(.04+i*.105));
function showToast(text,duration=1900){$('center-toast').innerHTML=text; $('center-toast').classList.add('show');toastUntil=performance.now()+duration;}
function showCountdown(){let n=3;const el=$('countdown');el.classList.add('show');el.classList.remove('go');el.textContent=n;
 const tick=()=>{n--;if(n>0){el.textContent=n;setTimeout(tick,700);}else if(n===0){el.textContent='GO';el.classList.add('go');eventStarted=true;setTimeout(()=>{el.classList.remove('show','go');},750);setTimeout(()=>{n=-1;tick();},700);} };setTimeout(tick,700);}
function setEvent(type) {
 selectedEvent=type; eventTime=0; checkpoint=0;eventStarted=false; finishAt=0;
 $('event-name').textContent=type==='free'?'FREE ROAM':type==='city'?'CITY SPRINT':'MOUNTAIN PASS';
 $('session-tag').textContent=type==='free'?'APEX CITY':'LIVE EVENT';
 $('race-row').style.display=type==='free'?'none':'flex';$('free-row').classList.toggle('on',type==='free');
 $('minimap-event').textContent=type==='mountain'?'PASS':type==='city'?'SPRINT':'CITY';
 raceCars.forEach((c,i)=>{c.progress=0;c.root.position.set(player.root.position.x+(i-1)*3.5,0,player.root.position.z+10+i*5);c.root.rotation.y=yaw;});
 if(type!=='free') showCountdown();
}
function startGame(type=selectedEvent) {
 $('loader').classList.add('hidden');$('menu').classList.add('hidden');$('pause').classList.add('hidden');$('result').classList.add('hidden');$('hud').classList.remove('hidden');
 playing=true;paused=false;player.root.position.set(0,0,9);yaw=0;speed=0;lateral=0;nitro=100;driftScore=0;combo=1;
 raceCars.forEach((c,i)=>{c.root.position.set((i-1)*3.3,0,18+i*5);c.root.rotation.y=0;});
 setEvent(type);clock.getDelta();
}
function pauseGame(){if(!playing)return;paused=true;$('pause').classList.remove('hidden');}
function resumeGame(){paused=false;$('pause').classList.add('hidden');clock.getDelta();}
function backToMenu(){playing=false;paused=false;$('hud').classList.add('hidden');$('pause').classList.add('hidden');$('result').classList.add('hidden');$('menu').classList.remove('hidden');$('menu').classList.remove('fading');}
function finishRace(){if(finishAt)return;finishAt=performance.now();eventStarted=false;setTimeout(()=>{$('result').classList.remove('hidden');$('result-time').textContent=formatTime(eventTime);$('result-best').textContent=formatTime(eventTime*.96);$('result-pos').textContent='1st';$('result-title').textContent=selectedEvent==='city'?'Valley champion.':'Summit secured.';},800);}
function formatTime(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${(t%60).toFixed(2).padStart(5,'0')}`;}
function resetCar(){player.root.position.set(0,0,9);yaw=0;speed=0;lateral=0;showToast('CAR RESET');}

// Control bindings are shared by keyboard, mouse, and multi-touch.
const keyMap={ArrowUp:'throttle',KeyW:'throttle',ArrowDown:'brake',KeyS:'brake',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'handbrake',ShiftLeft:'nitro',ShiftRight:'nitro'};
window.addEventListener('keydown',e=>{
 if(keyMap[e.code]){input[keyMap[e.code]]=true;e.preventDefault();}
 if(e.repeat)return;
 if(e.code==='Escape'||e.code==='KeyP'){paused?resumeGame():pauseGame();}
 if(e.code==='KeyC')cycleCamera();if(e.code==='KeyG')toggleMode();if(e.code==='KeyR')resetCar();
});
window.addEventListener('keyup',e=>{if(keyMap[e.code]){input[keyMap[e.code]]=false;e.preventDefault();}});
window.addEventListener('blur',()=>Object.keys(input).forEach(k=>input[k]=false));
document.querySelectorAll('[data-action]').forEach(btn=>{
 const action=btn.dataset.action;
 if(['left','right','throttle','brake','handbrake','nitro'].includes(action)){
  const down=e=>{e.preventDefault();input[action]=true;btn.classList.add('active');try{btn.setPointerCapture(e.pointerId);}catch{}};
  const up=e=>{e.preventDefault();input[action]=false;btn.classList.remove('active');};
  btn.addEventListener('pointerdown',down);['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,up));
 } else btn.addEventListener('click',()=>({mode:toggleMode,camera:cycleCamera,sound:toggleSound,reset:resetCar}[action]?.()));
});
function toggleMode(){driveMode=driveMode==='normal'?'drift':'normal';$('mode-label').innerHTML=`<i>MODE</i><b>${driveMode.toUpperCase()}</b>`;$('mode-label').classList.toggle('drift',driveMode==='drift');showToast(driveMode==='drift'?'DRIFT MODE':'GRIP MODE',900);}
function cycleCamera(){cameraMode=(cameraMode+1)%3;$('camera-label').innerHTML=`<i>CAM</i><b>${['HOOD','FOLLOW','FIXED'][cameraMode]}</b>`;showToast(['HOOD CAMERA','FOLLOW CAMERA','FIXED CAMERA'][cameraMode],900);}
function toggleSound(){soundOn=!soundOn;showToast(soundOn?'SOUND ON':'SOUND OFF',900);}
$('event-cards').addEventListener('click',e=>{const card=e.target.closest('.event-card');if(!card)return;document.querySelectorAll('.event-card').forEach(c=>c.classList.toggle('selected',c===card));selectedEvent=card.dataset.event;});
document.querySelectorAll('.event-card').forEach(card=>card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.click();}}));
$('start-btn').addEventListener('click',()=>startGame(selectedEvent));$('pause-btn').addEventListener('click',pauseGame);$('resume-btn').addEventListener('click',resumeGame);
$('restart-btn').addEventListener('click',()=>startGame(selectedEvent));$('freeroam-btn').addEventListener('click',()=>startGame('free'));$('menu-btn').addEventListener('click',backToMenu);
$('result-restart').addEventListener('click',()=>startGame(selectedEvent));$('result-free').addEventListener('click',()=>startGame('free'));$('result-menu').addEventListener('click',backToMenu);
document.querySelectorAll('[data-quality]').forEach(b=>b.addEventListener('click',()=>{quality=b.dataset.quality;document.querySelectorAll('[data-quality]').forEach(x=>x.classList.toggle('on',x===b));renderer.setPixelRatio(Math.min(devicePixelRatio||1,quality==='low'?.85:quality==='medium'?1.15:1.65));renderer.setSize(innerWidth,innerHeight);}));
document.querySelectorAll('[data-sound]').forEach(b=>b.addEventListener('click',()=>{soundOn=b.dataset.sound==='on';document.querySelectorAll('[data-sound]').forEach(x=>x.classList.toggle('on',x===b));}));
document.querySelectorAll('[data-shake]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('[data-shake]').forEach(x=>x.classList.toggle('on',x===b))));

// Event gates and a persistent minimap marker.
const gateGroup=new THREE.Group();scene.add(gateGroup);
const gateRing=new THREE.Mesh(new THREE.TorusGeometry(8,.42,8,36),new THREE.MeshBasicMaterial({color:0x42eaff}));gateRing.rotation.x=Math.PI/2;gateGroup.add(gateRing);
